        static List<Amount> C(params object[] kv)
        {
            var list = new List<Amount>();
            for (int i = 0; i + 1 < kv.Length; i += 2)
                list.Add(new Amount((string)kv[i], System.Convert.ToDouble(kv[i + 1])));
            return list;
        }
        static List<string> L(params string[] s) => new List<string>(s);
        static List<Effect> Fx_(params Effect[] e) => new List<Effect>(e);
        static Effect E(Fx kind, string of, double n) => new Effect(kind, of, n);
        static string T(string key) => Loc.T(key);
        static List<string> Lines(string key) => Loc.Lines(key);

