        static VisionDef Vision(Dream s, string k, bool great, bool rep, float deg, List<Offer> of,
                                List<Effect> effects, List<string> requires)
        {
            var v = new VisionDef
            {
                k = k, n = T("vision." + k + ".name"), bl = T("vision." + k + ".text"),
                fx = Lines("vision." + k + ".fx"), of = of, sel = 0, p = 0f, rep = rep, done = 0,
                great = great, a = false, angle = deg * Mathf.Deg2Rad, effects = effects, requires = requires
            };
            s.visions.Add(v);
            return v;
        }

