        static void Veil(Dream s, int ord, string name, double need, List<Amount> spend, List<Amount> bring,
                         int cap, double seconds, string entry)
        {
            var lines = Lines(entry);
            var reveal = new List<double>();
            for (int i = 0; i < lines.Count; i++) reveal.Add(System.Math.Floor(need * i / System.Math.Max(1, lines.Count)));
            s.veils.Add(new VeilDef
            {
                n = T(name), ord = ord, sunk = 0, need = need, spend = spend, bring = bring, w = 0, cap = cap,
                baseSeconds = seconds, entry = lines, reveal = reveal
            });
        }

